'use strict';
// Narrow recovery for rows generated by the failed I6.6 signed LIVE synthetic
// UAT (run 43470315730). No customer, insurer or payment business data touched.
const assert=require('node:assert/strict');
const admin=require('firebase-admin');
const TENANT='alianzas-soluciones';
const PREFIX='b4003qa_newpol_operativo_';
const START=PREFIX,END=PREFIX+'\uf8ff';
const COLLECTIONS=['actividades','vehiculos','carteraPrimas','recibosEsperados','polizas'];
const service=['SA_LAB','SA_ALT','SA_DEFAULT'].map(k=>process.env[k]).filter(Boolean)
  .map(s=>{try{return JSON.parse(s);}catch{return null;}})
  .find(s=>s?.type==='service_account'&&s.project_id==='ays-orbit-360-lab'&&s.private_key);
assert.ok(service,'I66_SYNTHETIC_CLEANUP_CREDENTIAL_UNAVAILABLE');
admin.initializeApp({credential:admin.credential.cert(service),projectId:'ays-orbit-360-lab'});
const tenant=admin.firestore().collection('tenants').doc(TENANT);
const col=name=>tenant.collection('data').doc(name).collection('items');
function identity(row){
  assert.equal(row.tenantId,TENANT,'I66_ORPHAN_WRONG_TENANT');
  assert.equal(row.pais,'GT','I66_ORPHAN_WRONG_COUNTRY');
  const client=String(row.clienteId||'');
  const match=client.match(/^b4003qa_newpol_operativo_([a-z0-9]+_[a-f0-9]{8})_client$/);
  assert.ok(match,'I66_ORPHAN_NOT_PROVEN_SYNTHETIC');
  const suffix=match[1],policy=PREFIX+suffix+'_policy',op='qa_newpolicy_operativo_'+suffix;
  return{client,policy,op,suffix};
}
function verify(name,doc,group){
  const row=doc.data()||{},id=identity(row);
  assert.equal(id.client,group.client,'I66_ORPHAN_MULTIPLE_CLIENTS');
  assert.equal(id.policy,group.policy,'I66_ORPHAN_MULTIPLE_POLICIES');
  const operation=String(row.operacionId||row.operationId||'');
  assert.equal(operation,group.op,'I66_ORPHAN_NOT_SAME_SIGNED_OPERATION_'+name);
  if(name==='actividades'){
    assert.equal(doc.id,'act_'+group.op,'I66_ORPHAN_ACTIVITY_ID_DRIFT');
  }else{
    assert.equal(name==='polizas'?doc.id:String(row.polizaId||''),group.policy,'I66_ORPHAN_POLICY_LINK_DRIFT_'+name);
  }
  if(name==='polizas')assert.equal(row.__syntheticQa,true,'I66_ORPHAN_POLICY_MARKER_MISSING');
  assert.ok(doc.updateTime,'I66_ORPHAN_MISSING_UPDATE_TIME');
}
async function read(){
  const group={client:'',policy:'',op:'',suffix:''},rows=[];
  for(const name of COLLECTIONS){
    const snap=await col(name).where('clienteId','>=',START).where('clienteId','<',END).limit(12).get();
    assert.ok(snap.size<12,'I66_ORPHAN_TOO_MANY_'+name);
    for(const doc of snap.docs){
      const id=identity(doc.data());
      if(!group.client)Object.assign(group,id);
      verify(name,doc,group);
      rows.push({name,ref:doc.ref,updateTime:doc.updateTime,id:doc.id});
    }
  }
  assert.ok(rows.length>0&&rows.length<=9,'I66_ORPHAN_COUNT_UNEXPECTED_'+rows.length);
  assert.ok(rows.some(x=>x.name==='actividades')&&rows.some(x=>x.name==='vehiculos')&&
    rows.some(x=>x.name==='recibosEsperados')&&rows.some(x=>x.name==='carteraPrimas'),
  'I66_ORPHAN_REQUIRED_LINKS_MISSING');
  for(const [name,key] of [['clientes','client'],['aseguradoras','insurer']]){
    const id=name==='clientes'?group.client:PREFIX+group.suffix+'_insurer';
    const doc=await col(name).doc(id).get();
    if(doc.exists){
      assert.equal(doc.data()?.__syntheticQa,true,'I66_ORPHAN_SEED_NOT_SYNTHETIC_'+name);
      assert.equal(doc.data()?.tenantId,TENANT);
      rows.push({name,ref:doc.ref,updateTime:doc.updateTime,id:doc.id});
    }
  }
  return{group,rows};
}
async function main(){
  const resp=await fetch('https://app.aysseguros.com/__recovery__/build.json',{headers:{'cache-control':'no-cache'}});
  assert.equal(resp.ok,true,'I66_ORPHAN_LIVE_BUILD_UNREACHABLE');
  const build=await resp.json();
  assert.equal(build.sourceSha,'8a0e904500cbb3c961d83f16517caab69df88a2b','I66_ORPHAN_LIVE_ROLLBACK_NOT_CONFIRMED');
  const before=await read();
  console.log('I66_ORPHAN_READ_ONLY_CENSUS_CONFIRMED '+JSON.stringify({operation:before.group.op,collectionCounts:Object.fromEntries(COLLECTIONS.map(n=>[n,before.rows.filter(r=>r.name===n).length])),seedCount:before.rows.filter(r=>['clientes','aseguradoras'].includes(r.name)).length}));
  for(const target of before.rows){
    const current=await target.ref.get();
    assert.ok(current.exists,'I66_ORPHAN_CHANGED_BEFORE_DELETE_'+target.name);
    if(COLLECTIONS.includes(target.name))verify(target.name,current,before.group);
    else assert.equal(current.data()?.__syntheticQa,true,'I66_ORPHAN_SEED_CHANGED');
    assert.equal(current.updateTime.toMillis(),target.updateTime.toMillis(),'I66_ORPHAN_CONCURRENT_UPDATE_HOLD');
    await target.ref.delete({lastUpdateTime:target.updateTime});
  }
  for(const name of COLLECTIONS){
    const after=await col(name).where('clienteId','>=',START).where('clienteId','<',END).limit(2).get();
    assert.equal(after.size,0,'I66_ORPHAN_REMAINING_'+name);
  }
  for(const [name,id] of [['clientes',before.group.client],['aseguradoras',PREFIX+before.group.suffix+'_insurer']])
    assert.equal((await col(name).doc(id).get()).exists,false,'I66_ORPHAN_SEED_REMAINING_'+name);
  console.log('I66_ORPHAN_PRECISE_SYNTHETIC_ONLY_BEFORE_AFTER_CLEANUP_PASS '+before.rows.length);
}
main().catch(e=>{console.error(e.stack||e);process.exitCode=1;});
